<?php require_once('../cred/config.php'); echo "<pre>"; echo "DB_SERVER: " . (defined('DB_SERVER') ? DB_SERVER : 'NOT DEFINED') . "\n"; echo "AI_DB_USER: " . (defined('AI_DB_USER') ? AI_DB_USER : 'NOT DEFINED') . "\n"; echo "AI_DB_NAME: " . (defined('AI_DB_NAME') ? AI_DB_NAME : 'NOT DEFINED') . "\n"; echo "AI_TABLE_PREFIX: " . (defined('AI_TABLE_PREFIX') ? AI_TABLE_PREFIX : 'NOT DEFINED') . "\n"; echo "pdo_ai exists: " . (isset($pdo_ai) ? 'YES' : 'NO — not set in config.php') . "\n"; if (isset($pdo_ai)) { try { $r = $pdo_ai->query("SHOW TABLES"); echo "Tables:\n"; while($row = $r->fetch(PDO::FETCH_NUM)) echo " - " . $row[0] . "\n"; } catch(Exception $e) { echo "Query error: " . $e->getMessage(); } } else { try { $t = new PDO( "mysql:host=".(defined('DB_SERVER')?DB_SERVER:'localhost'). ";dbname=".(defined('AI_DB_NAME')?AI_DB_NAME:'noorgeec_it').";charset=utf8mb4", defined('AI_DB_USER') ? AI_DB_USER : 'noorgeec_ai', defined('AI_DB_PASS') ? AI_DB_PASS : '' ); echo "Manual PDO connect: SUCCESS\n"; $r = $t->query("SHOW TABLES"); while($row = $r->fetch(PDO::FETCH_NUM)) echo " - " . $row[0] . "\n"; } catch(Exception $e) { echo "Manual connect FAILED: " . $e->getMessage(); } } echo "</pre>";
